/* Migração excepcional de Storage privado -> Cloudflare KV, apenas via cron.
 * Não cria rota HTTP, não publica segredos nem dados privados.
 * 8 arquivos por execução; o job para automaticamente quando não há pendências.
 */
async function migrarStoragePrivadoCron(env){
 if(!env.PRIVATE_D1||!env.PRIVATE_FILES_KV||!env.SUPABASE_SERVICE_ROLE_KEY||!env.SUPABASE_URL)return;
 const sql="SELECT f.owner,f.bucket,f.object_key,f.size_bytes,f.content_type FROM private_files f "+
 "LEFT JOIN private_file_transfer_errors e ON e.owner=f.owner AND e.bucket=f.bucket AND e.object_key=f.object_key "+
 "WHERE f.status='pending' AND coalesce(e.attempts,0)<3 ORDER BY coalesce(e.attempts,0),f.bucket,f.object_key LIMIT 8";
 const result=await env.PRIVATE_D1.prepare(sql).all();
 const base=new URL(env.SUPABASE_URL);
 if(base.protocol!=='https:'||!base.hostname.endsWith('.supabase.co'))return;
 for(const file of result.results||[]){
  const {owner,bucket,object_key:key}=file;
  if(!/^[0-9a-f-]{36}$/i.test(owner)||!['fotos','backups','aulas-figuras'].includes(bucket)||
    !key.startsWith(owner+'/')||key.length>512||key.includes('..')||key.includes('\\'))continue;
  let failure='erro_indefinido';
  try{
    const remote=base.origin+'/storage/v1/object/authenticated/'+encodeURIComponent(bucket)+'/'+key.split('/').map(encodeURIComponent).join('/');
    const response=await fetch(remote,{
      method:'GET',headers:{apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:'Bearer '+env.SUPABASE_SERVICE_ROLE_KEY},
      redirect:'error',signal:AbortSignal.timeout(16000)
    });
    if(!response.ok){failure='storage_http_'+response.status;throw Error('storage')};
    const bytes=await response.arrayBuffer(),size=Number(file.size_bytes);
    if(!bytes.byteLength||bytes.byteLength!==size||bytes.byteLength>8*1024*1024){
      failure='tamanho_divergente';throw Error('size');
    }
    const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)))
      .map(x=>x.toString(16).padStart(2,'0')).join('');
    const mime=typeof file.content_type==='string'&&/^(?:image\/(?:jpeg|png|webp|gif)|application\/(?:json|pdf|zip|octet-stream)|audio\/[\w.+-]+|text\/plain)$/i.test(file.content_type)
      ?file.content_type:'application/octet-stream';
    const kvkey=owner+':'+bucket+':'+key;
    await env.PRIVATE_FILES_KV.put(kvkey,bytes,{metadata:{mime,bytes:bytes.byteLength,sha256:sha}});
    const verified=await env.PRIVATE_FILES_KV.getWithMetadata(kvkey,'arrayBuffer');
    if(!verified?.value||verified.value.byteLength!==bytes.byteLength||verified.metadata?.sha256!==sha){
      failure='verificacao_kv';throw Error('verify');
    }
    const hash2=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',verified.value)))
      .map(x=>x.toString(16).padStart(2,'0')).join('');
    if(sha!==hash2){failure='hash_divergente';throw Error('hash')}
    await env.PRIVATE_D1.prepare(
      "UPDATE private_files SET status='ready',source='legado_admin_verificado',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE owner=? AND bucket=? AND object_key=? AND status='pending'"
    ).bind(owner,bucket,key).run();
  }catch(_){
    await env.PRIVATE_D1.prepare(
      "INSERT INTO private_file_transfer_errors(owner,bucket,object_key,error_code,attempts,updated_at) VALUES (?,?,?,?,1,strftime('%Y-%m-%dT%H:%M:%fZ','now')) "+
      "ON CONFLICT(owner,bucket,object_key) DO UPDATE SET error_code=excluded.error_code,attempts=private_file_transfer_errors.attempts+1,updated_at=excluded.updated_at"
    ).bind(owner,bucket,key,failure).run().catch(()=>{});
  }
 }
}
const radarScheduledAnterior=Nc.scheduled.bind(Nc);
Nc.scheduled=function(event,env,ctx){
 if(event.cron==='* * * * *'){
   ctx.waitUntil(migrarStoragePrivadoCron(env));
   return;
 }
 return radarScheduledAnterior(event,env,ctx);
};

